// Pure server-side policy. No Drive access, no credentials, no side effects.
// Call only with evidence generated by the trusted archive verifier and storage adapter,
// never with a client-provided assertion. The adapter must enforce storage-side CAS.
const HASH = /^[0-9a-f]{64}$/;
const revision = n => Number.isSafeInteger(n) && n >= 0;
const nonempty = s => typeof s === "string" && s.length > 0;
function inventory(items) {
  if (!Array.isArray(items)) throw new Error("inventory required");
  const map = new Map();
  for (const item of items) {
    if (!item || !HASH.test(item.sha256) || !Number.isSafeInteger(item.sizeBytes) ||
        item.sizeBytes < 0 || map.has(item.sha256)) throw new Error("invalid or duplicate original");
    map.set(item.sha256, item.sizeBytes);
  }
  return map;
}
function sameInventory(expected, actual) {
  const a = inventory(expected), b = inventory(actual);
  return a.size === b.size && [...a].every(([hash, bytes]) => b.get(hash) === bytes);
}
function validateSnapshot(s) {
  if (!s || !nonempty(s.libraryId) || !revision(s.revision) || !HASH.test(s.catalogueSha256))
    throw new Error("invalid snapshot");
  inventory(s.originals);
}
function validArchive(a) {
  return a && HASH.test(a.archiveSha256) && Number.isSafeInteger(a.archiveSizeBytes) &&
    a.archiveSizeBytes > 0;
}

// Returns the immutable publication intent. The verified catalogue digest must
// cover all metadata, positions, notes, relationships, history and tombstones.
// A missing original is never eligible, even if the legacy archive reader supports partial copies.
export function preparePublication(snapshot, verifiedArchive, previous, targetFileId) {
  validateSnapshot(snapshot);
  if (!nonempty(targetFileId)) throw new Error("stable Drive file ID required");
  if (!validArchive(verifiedArchive) || verifiedArchive.libraryId !== snapshot.libraryId ||
      verifiedArchive.revision !== snapshot.revision ||
      verifiedArchive.catalogueSha256 !== snapshot.catalogueSha256 ||
      !Array.isArray(verifiedArchive.missingHashes) || verifiedArchive.missingHashes.length !== 0 ||
      !sameInventory(snapshot.originals, verifiedArchive.originals))
    throw new Error("archive is not a complete verified snapshot");
  if (previous !== null) {
    if (!validArchive(previous) || previous.libraryId !== snapshot.libraryId ||
        previous.fileId !== targetFileId || !revision(previous.revision) ||
        !nonempty(previous.storageVersion)) throw new Error("invalid previous receipt");
    if (snapshot.revision <= previous.revision) throw new Error("snapshot not newer");
  }
  return Object.freeze({
    libraryId: snapshot.libraryId, revision: snapshot.revision, fileId: targetFileId,
    expectedStorageVersion: previous?.storageVersion ?? null,
    archiveSha256: verifiedArchive.archiveSha256, archiveSizeBytes: verifiedArchive.archiveSizeBytes
  });
}

// The storage adapter must implement a real conditional publication (or equivalent
// fail-safe single-writer primitive). A database lease + read-before-write is not CAS.
// If response was lost, recover the durable intent and read back the target, without
// issuing an unconditional replacement. A receipt never grants permission to write.
export function confirmPublication(intent, readBack, conditionalWriteReceipt) {
  if (!intent || !validArchive(intent) || !nonempty(intent.libraryId) ||
      !revision(intent.revision) || !nonempty(intent.fileId) ||
      !(intent.expectedStorageVersion === null || nonempty(intent.expectedStorageVersion)))
    throw new Error("invalid intent");
  if (!conditionalWriteReceipt || conditionalWriteReceipt.applied !== true ||
      conditionalWriteReceipt.fileId !== intent.fileId ||
      conditionalWriteReceipt.expectedStorageVersion !== intent.expectedStorageVersion ||
      !nonempty(conditionalWriteReceipt.storageVersion) ||
      conditionalWriteReceipt.storageVersion === intent.expectedStorageVersion)
    throw new Error("no conditional publication evidence");
  if (!validArchive(readBack) || readBack.fileId !== intent.fileId ||
      readBack.storageVersion !== conditionalWriteReceipt.storageVersion ||
      readBack.archiveSha256 !== intent.archiveSha256 ||
      readBack.archiveSizeBytes !== intent.archiveSizeBytes)
    throw new Error("published bytes did not verify");
  return Object.freeze({
    libraryId: intent.libraryId, revision: intent.revision, fileId: intent.fileId,
    archiveSha256: intent.archiveSha256, archiveSizeBytes: intent.archiveSizeBytes,
    storageVersion: readBack.storageVersion
  });
}
